// Bundles ../knowledge/*.md into src/server/knowledge.ts so the Vercel build (root = web/) can seed the database.
import { readdirSync, readFileSync, writeFileSync } from "node:fs";
import { join } from "node:path";
const dir = join(import.meta.dirname, "..", "..", "knowledge");
const docs = readdirSync(dir).filter((f) => f.endsWith(".md")).sort().map((f) => ({ source: f, text: readFileSync(join(dir, f), "utf8") }));
writeFileSync(join(import.meta.dirname, "..", "src", "server", "knowledge.ts"),
  "// Generated by scripts/gen-knowledge.mjs from ../knowledge — do not edit by hand.\nexport const SEED_DOCS: { source: string; text: string }[] = " + JSON.stringify(docs, null, 2) + ";\n");
console.log(`bundled ${docs.length} documents`);
